// Compares the JavaScript color math with reference values computed by the Python package
// (fixture.json, generated by generate_fixture.py). Run: node --test web/tests/
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { colorsFromStats, frameStats, linearToSrgb, srgbToLinear, SRGB_TO_LINEAR_LUT, toByteColor } from "../src/color.js";
import {
  columnColorIndex, defaultSampleCount, frameTime, outputName, ringRadius, sampleFrameIndices,
} from "../src/layout.js";

const fixture = JSON.parse(readFileSync(new URL("./fixture.json", import.meta.url), "utf8"));

test("sRGB to linear LUT matches Python", () => {
  assert.equal(SRGB_TO_LINEAR_LUT.length, 256);
  fixture.lut.forEach((v, i) => assert.ok(Math.abs(SRGB_TO_LINEAR_LUT[i] - v) < 1e-12, `entry ${i}`));
});

test("linear to sRGB inverts sRGB to linear on 8-bit values", () => {
  for (let i = 0; i < 256; i++) assert.equal(Math.round(linearToSrgb(srgbToLinear(i / 255)) * 255), i);
});

for (const c of fixture.cases) {
  test(`frame colors match Python: ${c.name}`, () => {
    const colors = colorsFromStats(frameStats(Uint8ClampedArray.from(c.rgba)));
    colors.avg.forEach((v, i) => assert.ok(Math.abs(v - c.avg[i]) < 1e-9, `avg channel ${i}: ${v} vs ${c.avg[i]}`));
    assert.deepEqual(colors.smoothed, c.smoothed);
    assert.deepEqual(colors.linear, c.linear);
  });
}

test("half black, half white frame: 128 averaged, 188 in linear light", () => {
  const c = fixture.cases.find((x) => x.name === "half_black_white");
  const colors = colorsFromStats(frameStats(Uint8ClampedArray.from(c.rgba)));
  assert.deepEqual(toByteColor(colors.avg), [128, 128, 128]);
  assert.deepEqual(colors.linear, [188, 188, 188]);
});

test("sampled frame indices match iter_sampled_frames", () => {
  for (const s of fixture.sampling) assert.deepEqual(sampleFrameIndices(s.frame_count, s.samples), s.indices);
});

test("default sample count is min(video width, frame count)", () => {
  assert.equal(defaultSampleCount(1920, 150000), 1920);
  assert.equal(defaultSampleCount(2048, 93), 93);
});

test("seek time is the middle of the frame, inside the video", () => {
  assert.equal(frameTime(0, 25, 10), 0.02);
  assert.equal(frameTime(10, 25, 10), 0.42);
  assert.ok(frameTime(1000, 25, 10) < 10);
});

test("horizontal columns stretch or pick colors evenly", () => {
  assert.deepEqual([0, 1, 2, 3].map((x) => columnColorIndex(x, 4, 2)), [0, 0, 1, 1]);
  assert.deepEqual([0, 1].map((x) => columnColorIndex(x, 2, 6)), [0, 3]);
});

test("circular rings: outer ring reaches the edge", () => {
  assert.equal(ringRadius(9, 10, 200), 100);
  assert.equal(ringRadius(0, 10, 200), 10);
});

test("output names follow the CLI", () => {
  assert.equal(outputName("My Movie.2001.mkv", "avg", "horizontal"), "My Movie.2001_avg_horizontal.png");
  assert.equal(outputName("clip", "avg_linear", "circular"), "clip_avg_linear_circular.png");
});
